import pytestfrom pyspark.sql.types import StructType, StructField, IntegerType, DoubleType, StringTypefrom pyspark.testing.utils import assertSchemaEqual  @pytest.fixture(scope="session")def spark():    """Créer une SparkSession locale, réutilisable pour toute la session de test"""    session = (        SparkSession.builder        .master("local[2]")        .appName("TestCSVOutput")        .config("spark.sql.shuffle.partitions", "2")        .config("spark.ui.enabled", "false")        .getOrCreate()    )    yield session    session.stop()     def test_csv_output(spark):    # Lire le CSV généré par l'ETL    df = spark.read.csv("output.csv", header=True, inferSchema=False)    # 1. Vérifier les noms de colonnes    expected_columns = ["user_id", "order_date", "amount", "status"]    assert set(df.columns) == set(expected_columns), f"Colonnes incorrectes : {df.columns}"    # 2. Vérifier les types    expected_schema = StructType([        StructField("user_id", IntegerType(), True),        StructField("order_date", StringType(), True),        StructField("amount", DoubleType(), True),        StructField("status", StringType(), True),    ])    actual_types = {f.name: f.dataType for f in df.schema.fields}    for field in expected_schema.fields:        assert field.name in actual_types, f"Colonne manquante : {field.name}"        assert actual_types[field.name] == field.dataType, \            f"Type de {field.name} incorrect : attendu {field.dataType}, obtenu {actual_types[field.name]}"    # 3. Règles métier : amount > 0    assert df.filter(F.col("amount") <= 0).count() == 0, "Présence de montants négatifs ou nuls"    # 4. Règles métier : status dans la liste autorisée    allowed = ["pending", "paid", "shipped"]    invalid = df.filter(~F.col("status").isin(allowed)).select("status").distinct().collect()    assert len(invalid) == 0, f"Valeurs de status invalides : {[r.status for r in invalid]}"    # 5. Règles métier : user_id non NULL    assert df.filter(F.col("user_id").isNull()).count() == 0, "user_id contient des valeurs NULL"